#include <stdio.h>

void treat(int *p) {
    *p = *p * 10;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int i;
    for (i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        treat(&x);
        printf("%d\n", x);
    }
    return 0;
}
